def total_cents(items, discount_percent=0):
    if type(discount_percent) is not int or not 0 <= discount_percent <= 100:
        raise ValueError('discount_percent must be an integer from 0 to 100')

    subtotal = 0
    for price, quantity in items:
        if type(price) is not int or price < 0:
            raise ValueError('price must be a nonnegative integer')
        if type(quantity) is not int or quantity <= 0:
            raise ValueError('quantity must be a positive integer')
        subtotal += price * quantity

    return subtotal * (100 - discount_percent) // 100
